RUNNER = "\nconst {pathToFileURL} = require('node:url');\nconst assert = require('node:assert/strict');\nconst puppeteer = require(process.env.STUDIO3D_PUPPETEER);\n(async () => {\n const browser = await puppeteer.launch({executablePath:process.env.PRODUCER_HEADLESS_SHELL_PATH,\n  headless:true, windowsHide:true, userDataDir:process.env.STUDIO3D_PROFILE, args:process.env.EDITING_PACK_3D_CAPTURE==='hardware' ? ['--use-angle=d3d11','--enable-webgl'] : ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--enable-webgl']});\n try {\n  const page = await browser.newPage(); const errors=[]; const remote=[];\n  page.on('pageerror', e=>errors.push(String(e)));\n  await page.setRequestInterception(true);\n  page.on('request',r=>{ const u=new URL(r.url());\n   if (u.protocol==='http:' && u.hostname==='127.0.0.1') r.continue();\n   else if (['data:','about:'].includes(u.protocol)) r.continue();\n   else {remote.push(r.url()); r.abort();} });\n  await page.goto(process.argv[2], {waitUntil:'networkidle0'});\n  await page.waitForFunction(()=>window.suite || window.loadError);\n  const result = await page.evaluate(async(processCapture)=>{\n   if(window.loadError) throw Error(window.loadError);\n   const {m,THREE}=window.suite; const checks=[];\n   function check(name, ok){if(!ok)throw Error(name);checks.push(name);}\n   check('zero-duration step',m.seg(1,1,0)===1 && m.seg(0,1,0)===0);\n   for(const args of [[0,0,-1],[NaN,0,1]]){\n    let failed=false;try{m.seg(...args)}catch{failed=true}check('invalid segment rejected '+args,failed);\n   }\n   let failed=false;try{m.createStage(document.createElement('canvas'),{width:0})}catch{failed=true}\n   check('invalid stage rejected',failed);\n   const canvas=document.querySelector('canvas');\n   const stage=m.createStage(canvas,{width:480,height:270,environmentIntensity:0.8,keyIntensity:1.5});\n   const {scene,camera,render,renderer}=stage;\n   check('landscape camera and fixed pixels',camera.aspect===480/270 && canvas.width===480 && canvas.height===270);\n   check('selected light parameters',scene.environmentIntensity===0.8 && stage.key.intensity===1.5);\n   const folder=m.makeFolder();scene.add(folder.group);camera.position.set(0,3.4,12);camera.lookAt(0,1,0);\n   const poses=[];\n   const renderAt=t=>{folder.hinge.rotation.x=0.65*m.outCubic(m.seg(t,0,1));\n    folder.group.position.x=-0.6+1.2*m.seg(t,0,2); render();poses.push(t)};\n   m.wireBeat({id:'probe',T0:5,DUR:2,renderAt,fontLoads:[]});await window.__hf.buildReady.probe;\n   function seek(t){window.dispatchEvent(new CustomEvent('hf-seek',{detail:{time:t}}))}\n   seek(5.4);const a=canvas.toDataURL();seek(6.6);const b=canvas.toDataURL();seek(5.4);\n   check('rendered A-B-A pixel determinism',a===canvas.toDataURL() && a!==b);\n   for(const t of [6.2,5,7,5.4])seek(t);check('shuffled seek pixel determinism',a===canvas.toDataURL());\n   const gl=renderer.getContext();const pixels=new Uint8Array(480*270*4);gl.readPixels(0,0,480,270,gl.RGBA,gl.UNSIGNED_BYTE,pixels);\n   let visible=0;for(let i=3;i<pixels.length;i+=4)if(pixels[i]>0)visible++;\n   check('nonblank canvas',visible>500);\n   const before=poses.length;seek(NaN);check('nonfinite seek ignored',poses.length===before);\n   seek(0);check('seek clamps start',poses.at(-1)===0);seek(99);check('seek clamps end',poses.at(-1)===2);\n   document.querySelector('#host').dataset.start='10';seek(10.5);check('live host offset',poses.at(-1)===0.5);\n   let replacement=0;\n   m.wireBeat({id:'probe',T0:10,DUR:2,renderAt:()=>replacement++,fontLoads:[]});await window.__hf.buildReady.probe;\n   const oldCount=poses.length;const newCount=replacement;seek(10.4);\n   check('same-id old listener removed',poses.length===oldCount && replacement===newCount+1);\n   window.__hf.beatDisposers.probe();const disposedCount=replacement;seek(11);\n   check('beat cleanup removes registry and listener',!window.__timelines.probe && replacement===disposedCount);\n   let release;const held=new Promise(r=>release=r);let heldRenders=0;\n   m.wireBeat({id:'held',T0:0,DUR:1,renderAt:()=>heldRenders++,fontLoads:[],ready:[held]});\n   window.__hf.beatDisposers.held();release();await held;await new Promise(r=>setTimeout(r,0));\n   check('disposed pending beat never warm-renders',heldRenders===0);\n   const expected=[];const originalError=console.error;console.error=(...a)=>expected.push(a.join(' '));\n   m.wireBeat({id:'bad',T0:0,DUR:1,renderAt:()=>{},fontLoads:[],ready:[Promise.reject(Error('missing required model'))]});\n   failed=false;try{await window.__hf.buildReady.bad}catch{failed=true}\n   check('failed dependency rejects readiness',failed && expected.length===1);console.error=originalError;\n   window.__hf.beatDisposers.bad();\n   const originalLoad=document.fonts.load.bind(document.fonts);\n   document.fonts.load=async()=>[];console.error=(...a)=>expected.push(a.join(' '));\n   m.wireBeat({id:'font-failure',T0:0,DUR:1,renderAt:()=>{},fontLoads:['700 84px MissingRequiredFont']});\n   failed=false;try{await window.__hf.buildReady['font-failure']}catch{failed=true}\n   check('missing required font rejects readiness',failed);\n   document.fonts.load=originalLoad;console.error=originalError;window.__hf.beatDisposers['font-failure']();\n   for(const load of [m.loadImage,m.loadTexture]){\n    failed=false;try{await load('/missing-required.png')}catch{failed=true}check('required loader rejects '+load.name,failed);\n   }\n   const png='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jGJkAAAAASUVORK5CYII=';\n   const color=await m.loadTexture(png);const data=await m.loadTexture(png,{color:false});\n   check('color versus data texture space',color.colorSpace===THREE.SRGBColorSpace && data.colorSpace===THREE.NoColorSpace);\n   color.dispose();data.dispose();\n   let materialDisposed=0; m.MAT.folderFront.addEventListener('dispose',()=>materialDisposed++);\n   stage.dispose();stage.dispose();check('stage cleanup preserves shared materials',materialDisposed===0 && scene.environment===null);\n   const portrait=m.createStage(document.createElement('canvas'),{floor:false});\n   check('legacy portrait defaults preserved',portrait.camera.aspect===1080/1920 && portrait.renderer.domElement.width===1080);\n   portrait.dispose();\n   const dbg=gl.getExtension('WEBGL_debug_renderer_info');const gpu=dbg?gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL):gl.getParameter(gl.RENDERER);if(processCapture==='software')check('software renderer verified',/SwiftShader/i.test(gpu));return {checks,visible_pixels:visible,revision:THREE.REVISION,gpu};\n  },process.env.EDITING_PACK_3D_CAPTURE || 'software');\n  assert.deepEqual(errors,[]);assert.deepEqual(remote,[]);\n  console.log(JSON.stringify({...result,page_errors:errors,remote_requests:remote}));\n } finally {await browser.close();}\n})().catch(e=>{console.error(e);process.exitCode=1});\n"
class QuietHandler(http.server.SimpleHTTPRequestHandler):
 def log_message(self,*args):pass
class StudioBrowserTests(unittest.TestCase):
 def test_offline_scene_lifecycle_readiness_and_random_seek(self):
  resources=runtime.studio_resources()
  scratch=runtime.output(runtime.workspace_root()/'cache/studio-tests',require_workspace=True)
  scratch.mkdir(parents=True,exist_ok=True)
  with tempfile.TemporaryDirectory(prefix='site-',dir=scratch) as tmp:
   site=Path(tmp)
   staged={'three.module.js':resources['three_module'],'three.core.js':resources['three_core'],'addons/environments/RoomEnvironment.js':resources['room_environment'],'gsap.min.js':resources['gsap_runtime']}
   for name,source in staged.items():
    dest=site/name;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(source,dest)
   shutil.copyfile(runtime.root()/'Editing_OS/Skills/studio-3d-objects/starter/studio3d.js',site/'studio3d.js')
   html='<!doctype html><meta charset="utf-8"><canvas></canvas><div id="host" data-composition-id="probe" data-start="5"></div><script src="gsap.min.js"></script>'
   html+='<script type="importmap">'+json.dumps({'imports':{'three':'./three.module.js','three/addons/':'./addons/'}})+'</script>'
   html+='<script type="module">try{const m=await import("./studio3d.js");window.suite={m,THREE:m.THREE}}catch(e){window.loadError=String(e)}</script>'
   (site/'index.html').write_text(html,encoding='utf-8');(site/'runner.cjs').write_text(RUNNER,encoding='utf-8')
   server=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(QuietHandler,directory=str(site)))
   thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
   env=runtime.child_env();env['STUDIO3D_PROFILE']=str(site/'browser-profile');env['STUDIO3D_PUPPETEER']=str(resources['puppeteer_entry']);env['PRODUCER_HEADLESS_SHELL_PATH']=str(resources['browser']);env.setdefault('EDITING_PACK_3D_CAPTURE','software')
   self.assertIn(env['EDITING_PACK_3D_CAPTURE'],('software','hardware'))
   try:
    process=subprocess.Popen([str(resources['node']),str(site/'runner.cjs'),f'http://127.0.0.1:{server.server_port}/index.html'],env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,encoding='utf-8',errors='replace',**runtime.child_kwargs())
    try:
     stdout,stderr=process.communicate(timeout=180)
    except subprocess.TimeoutExpired:
     if process.poll() is None:
      if os.name=='nt':subprocess.run(['taskkill','/PID',str(process.pid),'/T','/F'],capture_output=True,**runtime.child_kwargs())
      else:process.kill()
     stdout,stderr=process.communicate();(scratch/'timeout.log').write_text(stdout+'\n'+stderr,encoding='utf-8');raise
    result=subprocess.CompletedProcess(process.args,process.returncode,stdout,stderr)
    (scratch/'browser-regression.log').write_text(result.stdout+'\n'+result.stderr,encoding='utf-8')
    self.assertEqual(result.returncode,0,result.stdout+'\n'+result.stderr)
    report=json.loads(result.stdout.strip().splitlines()[-1]);self.assertGreaterEqual(len(report['checks']),24);self.assertEqual(report['revision'],'185');self.assertEqual(report['remote_requests'],[])
    (scratch/'browser-regression.json').write_text(json.dumps(report,indent=2),encoding='utf-8');print(json.dumps(report))
   finally:
    server.shutdown();server.server_close();thread.join(timeout=5)
if __name__=='__main__':unittest.main()
